mapper.select:
select id, content, status, feedback, created_at, reviewed_at
from task_submission
where student_task_id = #{studentTaskId} and request_key = #{requestKey}

mapper.update:
update task_submission
set status = 'RETURNED', feedback = #{feedback}, reviewed_at = current_timestamp, reviewed_by = #{reviewer}
where id = #{submissionId}

update task_submission
set status = 'COMPLETED', feedback = #{feedback}, reviewed_at = current_timestamp, reviewed_by = #{reviewer}
where id = #{submissionId}
